function say(t){notice=t;$('#status').textContent=t;drawMenu();}
function dispose(root){const materials=new Set(),textures=new Set();root.traverse(o=>{o.geometry?.dispose();const pair=materialPairs.get(o);for(const m of [o.material,pair?.original,pair?.flat].flat().filter(Boolean)){materials.add(m);if(m.map)textures.add(m.map);}});materials.forEach(m=>m.dispose());textures.forEach(t=>t.dispose());}
