function remember(){if(restoring)return;undo.push(capture());if(undo.length>20)undo.shift();}
function setActive(e,piece=null){active=e;selectedPiece=piece;if(piece&&freeMembership.has(piece))activeFree=freeMembership.get(piece);updateVisibility();drawMenu();}
