function wrap(text,x,y,maxWidth,lineHeight,maxLines=3){let line='',row=0;for(const word of text.split(' ')){const next=line+word+' ';if(ctx.measureText(next).width>maxWidth&&line){ctx.fillText(line,x,y+row*lineHeight);line=word+' ';if(++row>=maxLines)return;}else line=next;}ctx.fillText(line,x,y+row*lineHeight);}
function drawMenu(){if(!ctx)return;$('#layout').textContent=layoutMode==='free'?'Tryb: Własny układ':'Tryb: Według skanu';ctx.fillStyle='#111d27';ctx.fillRect(0,0,1024,1280);ctx.fillStyle='#f0f7e6';ctx.font='40px sans-serif';ctx.fillText('PRACOWNIA • VR 2',40,58);ctx.font='30px sans-serif';const p=atlas?.pages[cursor];ctx.fillText(p?`f${p.label}  ·  ${cursor+1} / ${atlas.pages.length}  ·  ${kind}`:'Ładowanie…',40,110);ctx.font='25px sans-serif';ctx.fillStyle='#c0d9e2';ctx.fillText(`${layoutMode==='free'?'WŁASNY UKŁAD':'WEDŁUG SKANU'} · grupa ${activeFree?freeGroups.indexOf(activeFree)+1:'—'} · zestawy ${entries.length}`,40,151);areas.length=0;
 for(let i=0;i<3;i++){const x=32+i*330,y=178,w=304,h=76;ctx.fillStyle=menuTab===i?'#a8d7ec':'#30424f';ctx.fillRect(x,y,w,h);ctx.fillStyle=menuTab===i?'#11232d':'#fff';ctx.font='29px sans-serif';ctx.fillText(['KARTY','SKŁADANIE','WŁASNY UKŁAD'][i],x+12,y+49);areas.push({x,y,w,h,action:()=>{menuTab=i;drawMenu();}});}
 const list=actions[menuTab];for(let i=0;i<list.length;i++){const x=32+(i%2)*496,y=278+Math.floor(i/2)*102,w=464,h=88;ctx.fillStyle='#294553';ctx.fillRect(x,y,w,h);ctx.fillStyle='#fff';ctx.font='32px sans-serif';ctx.fillText(list[i][0],x+20,y+55);areas.push({x,y,w,h,action:list[i][1]});}
 ctx.fillStyle='#bfeaa6';ctx.font='25px sans-serif';ctx.fillText(`Snap: ${snap&&layoutMode==='source'?'TAK':'NIE'} · skan: ${reference?'TAK':'NIE'} · tło: ${backplate?'TAK':'NIE'}`,40,930);ctx.fillText(`Kolory: ${readable?'ORYGINALNE / BEZ CIENI':'OŚWIETLENIE 3D'}`,40,968);ctx.fillStyle='#a8d7ec';wrap(assistText||(layoutMode==='free'?'Ustaw dowolnie → Dołącz wybrany. Bez zmiany pozycji.':'Wybierz fragment spustem. Zielony cel = puść.'),40,1015,940,32,2);ctx.fillStyle='#fff';ctx.font='26px sans-serif';wrap(notice,40,1090,940,33,2);ctx.fillStyle='#c0d9e2';ctx.font='25px sans-serif';ctx.fillText('SPUST: część / grupa • GRIP: cały zestaw',40,1200);ctx.fillText('DRĄŻEK: odległość • perspektywa śledzona',40,1243);menuTexture.needsUpdate=true;}
function positionMenu(){const cam=renderer.xr.getCamera();cam.getWorldPosition(v3);cam.getWorldQuaternion(q4);const yaw=new THREE.Euler().setFromQuaternion(q4,'YXZ').y;menu.position.copy(v3).add(new THREE.Vector3(-.78,-.02,-1.15).applyAxisAngle(new THREE.Vector3(0,1,0),yaw));menu.rotation.set(0,yaw+.32,0);}
function hits(h){h.controller.updateWorldMatrix(true,false);raycaster.ray.origin.setFromMatrixPosition(h.controller.matrixWorld);raycaster.ray.direction.set(0,0,-1).applyQuaternion(h.controller.getWorldQuaternion(new THREE.Quaternion()));const objects=[...(menu.visible?[menu]:[]),...entries.flatMap(e=>e.pieces.filter(p=>!hands.some(h=>h.held?.object===p)))];return raycaster.intersectObjects(objects,true).find(hit=>{let o=hit.object;while(o){if(!o.visible)return false;o=o.parent;}return true;});}
function entryOf(obj){let p=obj;while(p){const id=p.userData.entryId||p.userData.assembly;if(id)return entries.find(e=>e.id===id);p=p.parent;}return null;}
function pieceOf(entry,obj){let p=obj;while(p&&!entry.pieces.includes(p))p=p.parent;return p;}
function begin(h,whole){if(h.held)return;const hit=hits(h);if(!hit)return;if(hit.object===menu){if(whole)return;const x=hit.uv.x*1024,y=(1-hit.uv.y)*1280;const area=areas.find(a=>x>=a.x&&x<=a.x+a.w&&y>=a.y&&y<=a.y+a.h);if(area&&(!busy||area.action===exitXR))Promise.resolve(area.action()).catch(()=>say('Operacja nie powiodła się.'));return;}if(busy)return;const entry=entryOf(hit.object);if(!entry)return;const piece=pieceOf(entry,hit.object);if(!piece)return;const free=freeMembership.get(piece);const object=whole?(free?.root||entry.root):free?free.root:entry.joined.has(piece.name)?entry.cluster:piece;if(!canGrab(entry,object,hands.map(x=>x.held))){say('Ten obiekt jest już trzymany. Drugą ręką możesz chwycić luźną część.');return;}remember();setActive(entry,piece);h.controller.attach(object);h.held={object,entry,whole,free:!!free,cluster:object===entry.cluster};h.input?.gamepad?.hapticActuators?.[0]?.pulse(.25,40);}
